((root)=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const imageURL=key=>key?.startsWith('/media/')?key:key==='photo'?'/assets/hero.png':['office','popup'].includes(key)?'/assets/'+key+'-3d.png':key==='a-home'?'/assets/home-3d-v2.png':key?'/assets/space-illustrations.png':'';
 const visual=(key,alt='')=>key?.startsWith('/media/')||['photo','office','popup'].includes(key)?'<img src="'+esc(imageURL(key))+'" alt="'+esc(alt)+'" loading="lazy">':key?'<div class="cms-sprite '+esc(key)+'" role="img" aria-label="'+esc(alt)+'"></div>':'<div class="cms-empty-cover">대표 사진을 선택해주세요.</div>';
 function blocks(p){return (p.blocks||p.sections?.flatMap(s=>[...(s[0]?[{type:'heading',text:s[0]}]:[]),...(s[1]?[{type:'paragraph',text:s[1]}]:[]),...(s[2]?[{type:'image',src:s[2],alt:s[0]}]:[])])||[]).map(b=>({...b,font:b.font||'inherit'}));}
 function related(p,type,pool){const others=pool.filter(x=>x.id!==p.id);if(p.relatedMode==='random'||!p.relatedMode){let seed=2166136261;for(const c of String(p.id||p.title)+new Date().toISOString().slice(0,10))seed=Math.imul(seed^c.charCodeAt(0),16777619);return others.map(x=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return {x,key:seed>>>0};}).sort((a,b)=>a.key-b.key).slice(0,3).map(x=>x.x);}if(p.relatedMode!=='manual')return [];return (p.related||[]).map(id=>others.find(x=>x.id===id)).filter(Boolean);}
 function render(p,type,pool=[],edit=false){
  const field=(key,tag,value,classes='')=>'<'+tag+' class="'+classes+'"'+(edit?' contenteditable="plaintext-only" data-edit-field="'+key+'" aria-label="'+esc(({title:'제목',lead:'짧은 소개',intro:'공간 소개',introTitle:'공간 소개 제목',flowTitle:'경험의 흐름 제목',noteTitle:'디자인 노트 제목',note:'디자인 노트',relatedTitle:'관련 글 제목'})[key]||key)+'" data-placeholder="클릭해서 내용을 입력하세요"':'')+'>'+root.NEMO_RICH.markup(p.richText?.[key],String(value??''))+'</'+tag+'>';
  const price=p.price||{},prices=type==='portfolio'&&price.mode&&price.mode!=='none'?'<dl class="cms-prices">'+(['unit','both'].includes(price.mode)&&price.unit?'<div><dt>평당 단가</dt><dd>'+esc(price.unit)+'</dd></div>':'')+(['total','both'].includes(price.mode)&&price.total?'<div><dt>총 견적</dt><dd>'+esc(price.total)+'</dd></div>':'')+'</dl>':'';
  const photos=[...new Set([p.visual,...blocks(p).filter(b=>b.type==='image').map(b=>b.src),...(p.images||[])].filter(Boolean))];const gallery=!edit&&photos.length>1?'<div class="cms-gallery" tabindex="0" aria-label="사진 슬라이드">'+photos.map((src,i)=>'<div class="cms-slide" data-gallery-src="'+esc(src)+'" '+(i?'hidden':'')+'>'+visual(src,p.title)+'</div>').join('')+'<div class="cms-gallery-controls"><button type="button" data-slide="-1" aria-label="이전 사진">←</button><span aria-live="polite">1 / '+photos.length+'</span><button type="button" data-slide="1" aria-label="다음 사진">→</button></div></div>':'';const cover='<div class="cms-cover"'+(edit?' data-edit-cover="true" tabindex="0" aria-label="대표 사진 선택"':'')+'>'+(gallery||visual(p.visual,p.title))+(edit?'<span class="cms-cover-hint">클릭해서 대표 사진 선택</span>':'')+'</div>';
  const heading='<div class="cms-heading"><span class="cms-meta">'+esc(type==='portfolio'?[...new Set([p.category,p.style,p.kind,p.isActual?'실제 프로젝트':''].filter(Boolean))].join(' · '):[p.category,(p.time||'1분')+' 읽기'].join(' · '))+'</span>'+field('title','h1',p.title||'','cms-title')+field('lead','p',p.lead||'','cms-lead')+prices+'</div>';
  const hero='<header class="cms-hero cms-hero-'+(p.heroLayout||(type==='news'?'text-top':'side'))+' '+(type==='news'?'cms-news-hero':'')+'">'+(p.heroLayout==='image-top'||(type==='portfolio'&&p.heroLayout!=='text-top')?cover+heading:heading+cover)+'</header>';
  const intro=type==='portfolio'?'<section class="cms-intro">'+field('introTitle','h2',p.introTitle||'공간 소개')+field('intro','p',p.intro||'')+(p.points?.length?'<div class="cms-points">'+p.points.map(s=>'<span>'+esc(s)+'</span>').join('')+'</div>':'')+'</section>':'';
  const content=blocks(p).map((b,i)=>{const controls=edit?'<div class="cms-block-tools"><button type="button" class="block-grip" draggable="false" data-drag-block="'+i+'" aria-label="'+(i+1)+'번 요소 끌어서 이동">⠿</button><span>'+({heading:'소제목',paragraph:'문단',image:'사진',youtube:'유튜브'})[b.type]+'</span><button type="button" data-block-action="up" data-index="'+i+'" aria-label="'+(i+1)+'번 요소 위로">↑</button><button type="button" data-block-action="down" data-index="'+i+'" aria-label="'+(i+1)+'번 요소 아래로">↓</button><button type="button" data-block-action="remove" data-index="'+i+'" aria-label="'+(i+1)+'번 요소 삭제">×</button></div>':'';
   const body=b.type==='youtube'?(edit?'<div class="cms-video-edit"><strong>YouTube</strong><label>유튜브 주소<input data-video-url="'+i+'" value="'+esc(b.url||'https://www.youtube.com/watch?v='+b.videoId)+'" placeholder="https://www.youtube.com/watch?v=…"></label></div>':youtubeId(b.videoId||b.url)?'<div class="cms-video"><iframe src="https://www.youtube-nocookie.com/embed/'+youtubeId(b.videoId||b.url)+'" title="유튜브 동영상" loading="lazy" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div>':''):b.type==='image'?'<figure class="cms-photo cms-photo-'+(b.size||'auto')+' cms-align-'+(b.align||'center')+(b.width&&b.height&&b.width/b.height<.9?' cms-photo-portrait':'')+'">'+visual(b.src,b.alt)+'<figcaption'+(edit?' contenteditable="plaintext-only" data-block-caption="'+i+'" aria-label="사진 설명"':'')+'>'+root.NEMO_RICH.markup(b.captionRuns,String(b.alt??''))+'</figcaption></figure>':'<'+(b.type==='heading'?'h2':'p')+(edit?' contenteditable="plaintext-only" data-edit-block="'+i+'" aria-label="'+(i+1)+'번 '+(b.type==='heading'?'소제목':'문단')+'" data-placeholder="내용을 입력하세요"':'')+'>'+root.NEMO_RICH.markup(b.runs,String(b.text??''))+'</'+(b.type==='heading'?'h2':'p')+'>';
   return '<div class="cms-block '+(b.type==='image'?'cms-image-block '+(b.width&&b.height&&b.width/b.height<.9&&(!b.size||b.size==='auto')?'cms-portrait-pair ':''):'')+'cms-width-'+(b.layout==='half'?'half':'full')+' cms-font-'+esc(b.font||'inherit')+'" data-block-index="'+i+'">'+controls+body+'</div>';
  }).join('');
  const narrative='<section class="cms-narrative">'+(type==='portfolio'?field('flowTitle','h2',p.flowTitle||'경험의 흐름','cms-flow-title'):'')+content+(edit?'<div class="cms-insert-end"><button type="button" data-add-block="paragraph">＋ 문단</button><button type="button" data-add-block="heading">＋ 소제목</button><button type="button" data-add-block="image">＋ 사진</button><button type="button" data-add-block="youtube">＋ 유튜브</button></div>':'')+'</section>';
  const note=type==='portfolio'&&p.showNote!==false?'<section class="cms-note"><span class="cms-meta">NEMO DESIGN NOTE</span>'+field('noteTitle','h2',p.noteTitle||'디자인 노트')+field('note','p',p.note??[p.lead,p.intro].filter(Boolean).join(' '))+'</section>':'';
  const chosen=related(p,type,pool),relatedSection=chosen.length?'<section class="cms-related">'+field('relatedTitle','h2',p.relatedTitle||(type==='portfolio'?'다른 공간도 살펴보세요.':'이런 이야기도 있어요.'))+'<div>'+chosen.map(x=>'<a href="/'+(type==='portfolio'?'portfolio.html?project=':'story.html?article=')+encodeURIComponent(x.id)+'">'+visual(x.visual,x.title)+'<span>'+esc(x.category)+'</span><h3>'+esc(x.title)+'</h3></a>').join('')+'</div></section>':edit?'<p class="cms-related-empty">관련 글은 위의 글 설정에서 선택하세요.</p>':'';
  const contact='<aside class="cms-contact"><h2>생각한 공간을 함께 이야기해요.</h2><a href="/inquiry.html'+(type==='portfolio'?'?space='+encodeURIComponent(p.category)+'&amp;project='+encodeURIComponent(p.id||''):'')+'">상담 신청하기 ↗</a></aside>';
  let toc='';if(p.showToc!==false){const entries=[...(type==='portfolio'?[['intro',p.introTitle||'공간 소개']]:[]),...blocks(p).map((b,i)=>b.type==='heading'?['block-'+i,b.text]:null).filter(Boolean),...(type==='portfolio'&&p.showNote!==false?[['note',p.noteTitle||'디자인 노트']]:[])];toc=entries.length?'<nav class="cms-toc" aria-label="목차"><strong>목차</strong>'+entries.map(([id,title])=>'<a href="#cms-'+id+'">'+esc(title||'소제목')+'</a>').join('')+'</nav>':'';}return '<article class="cms-document cms-font-'+(p.font==='serif'?'serif':'sans')+(edit?' cms-editing':'')+'">'+hero+toc+intro+narrative+note+relatedSection+contact+'</article>';
 }
 function layout(container){
  bind(container);
  const imageElements=[...container.querySelectorAll('img')];
  for(const img of imageElements){const apply=()=>{if(!img.naturalWidth||!img.naturalHeight)return;const ratio=img.naturalWidth/img.naturalHeight;img.style.setProperty('--cms-native-width',img.naturalWidth+'px');const figure=img.closest('.cms-photo');if(figure){figure.classList.toggle('cms-photo-portrait',ratio<.9);figure.classList.toggle('cms-photo-wide',ratio>1.3);figure.style.setProperty('--cms-ratio',String(ratio));const block=figure.closest('.cms-image-block');block?.classList.toggle('cms-portrait-pair',ratio<.9&&figure.classList.contains('cms-photo-auto'));}const cover=img.closest('.cms-cover');if(cover){cover.classList.toggle('cms-cover-portrait',ratio<.9);cover.style.setProperty('--cms-ratio',String(ratio));}const card=img.closest('.portfolio-item');if(card&&!card.closest('.cms-related')){card.style.setProperty('--card-ratio',String(Math.max(.65,Math.min(1.8,ratio))));card.classList.toggle('card-portrait',ratio<.9);}};if(img.complete)apply();else img.addEventListener('load',apply,{once:true});
  }
 }
 function youtubeId(value){if(/^[A-Za-z0-9_-]{11}$/.test(value||''))return value;try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol))return '';let id=u.hostname==='youtu.be'?u.pathname.split('/')[1]:['youtube.com','www.youtube.com','m.youtube.com','www.youtube-nocookie.com'].includes(u.hostname)?(u.searchParams.get('v')||u.pathname.match(/^\/(?:embed|shorts)\/([^/]+)/)?.[1]):'';return /^[A-Za-z0-9_-]{11}$/.test(id||'')?id:'';}catch{return '';}}
 function bind(container){container.querySelectorAll('.cms-intro').forEach(el=>el.id='cms-intro');container.querySelectorAll('.cms-note').forEach(el=>el.id='cms-note');container.querySelectorAll('.cms-block:has(h2)').forEach(el=>el.id='cms-block-'+el.dataset.blockIndex);container.querySelectorAll('.cms-gallery').forEach(el=>{if(el.dataset.bound)return;el.dataset.bound='true';let index=0,start=0;const slides=[...el.querySelectorAll('.cms-slide')],move=n=>{index=(index+n+slides.length)%slides.length;slides.forEach((x,i)=>x.hidden=i!==index);el.querySelector('[aria-live]').textContent=(index+1)+' / '+slides.length;};el.addEventListener('click',e=>{const b=e.target.closest('[data-slide]');if(b){e.stopPropagation();move(Number(b.dataset.slide));}});el.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();e.stopPropagation();move(e.key==='ArrowLeft'?-1:1);}});el.addEventListener('touchstart',e=>start=e.changedTouches[0].clientX,{passive:true});el.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-start;if(Math.abs(delta)>45)move(delta>0?-1:1);},{passive:true});});}
 root.NEMO_RENDER={render,blocks,visual,imageURL,esc,layout,youtubeId,bind};
 if(typeof module!=='undefined')module.exports=root.NEMO_RENDER;
})(typeof window==='undefined'?globalThis:window);
